"use strict";(self.webpackChunkenablemodel=self.webpackChunkenablemodel||[]).push([[891],{7967:(e,t,i)=>{i.r(t),i.d(t,{assets:()=>l,contentTitle:()=>o,default:()=>h,frontMatter:()=>a,metadata:()=>s,toc:()=>c});const s=JSON.parse('{"id":"forces-that-disable/precarity","title":"Precarity","description":"When stability is refused -- and possibilities collapse.","source":"@site/docs/forces-that-disable/precarity.md","sourceDirName":"forces-that-disable","slug":"/forces-that-disable/precarity","permalink":"/docs/forces-that-disable/precarity","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Precarity"},"sidebar":"tutorialSidebar","previous":{"title":"Disinformation and Misinformation","permalink":"/docs/forces-that-disable/disinformation_misinformation"},"next":{"title":"Manifestations","permalink":"/docs/category/manifestations"}}');var n=i(4848),r=i(8453);const a={title:"Precarity"},o=void 0,l={},c=[{value:"What It Is",id:"what-it-is",level:2},{value:"Why It Happens",id:"why-it-happens",level:2},{value:"Where It Happens (ENABLE Stages)",id:"where-it-happens-enable-stages",level:2},{value:"How It Disables",id:"how-it-disables",level:2},{value:"Why It Matters",id:"why-it-matters",level:2},{value:"Real-World Examples",id:"real-world-examples",level:2},{value:"What Care Sounds Like",id:"what-care-sounds-like",level:2},{value:"What Neglect Sounds Like",id:"what-neglect-sounds-like",level:2}];function d(e){const t={a:"a",admonition:"admonition",blockquote:"blockquote",em:"em",h2:"h2",hr:"hr",li:"li",ol:"ol",p:"p",section:"section",strong:"strong",sup:"sup",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,r.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.p,{children:"When stability is refused -- and possibilities collapse."}),"\n",(0,n.jsx)(t.h2,{id:"what-it-is",children:"What It Is"}),"\n",(0,n.jsx)(t.p,{children:"Precarity is a disabling force. It occurs when the stability that people need to function -- steady work, predictable support, consistent access, survivable workloads, reliable infrastructure, or safe institutional footing -- is absent, fragile, or constantly under threat."}),"\n",(0,n.jsx)(t.p,{children:"Precarity removes guarantees. It creates environments where nothing can be counted on: not funding, not mentors, not benefits, not accommodations, not continuity of tools, not the systems required to survive. In precarious environments, lives and careers are built atop shifting ground. What should be reliable becomes vulnerable to collapse."}),"\n",(0,n.jsx)(t.p,{children:"Precarity reduces pathways. It collapses the number of viable routes a person can take -- toward education, stable work, mentorship, healthcare, relationships, or long-term goals. Under precarity, the same individual has fewer possible futures. When stable routes are removed, the life a person could have lived becomes inaccessible."}),"\n",(0,n.jsx)(t.p,{children:"Precarity is not accidental -- it is engineered. Institutions create instability when they refuse to build the durable structures that disabled people need to survive and participate, replacing stability with risk and leaving disabled people to absorb the consequences alone."}),"\n",(0,n.jsx)(t.p,{children:"Precarity causes harm. It erodes agency, interrupts continuity, and forces people to divert energy away from growth and toward survival. When the environment is chronically unstable, long-term plans become fragile, progress stalls, and the conditions required for health, safety, and participation deteriorate -- not because of individual limitations, but because stability was never provided."}),"\n",(0,n.jsx)(t.p,{children:"Precarity can operate in plain sight. It's visible when institutions exploit contingent labor, replace stable roles with disposable labor, rotate people through short-term positions that cannot sustain access, or leave accessibility teams understaffed, roles unfilled, mandates unfunded, and support unpredictable. Its harm is not hidden; organizations normalize it as the cost of participation."}),"\n",(0,n.jsx)(t.p,{children:"Precarity is maintained. Institutions keep fragile arrangements in place -- temporary roles, unstable funding, understaffed teams, and short-term contracts -- long after the consequences are known. Instability becomes routine."}),"\n",(0,n.jsx)(t.p,{children:"Precarity is assigned. The people who authorize unstable systems are rarely the ones required to live inside them -- and would not accept such conditions for themselves. They offload instability to those whose options are constrained -- disabled people, contingent workers, junior staff, or anyone with the least power to refuse it. Risk is externalized, not shared."}),"\n",(0,n.jsx)(t.p,{children:"Precarity is historically given. Institutions hand disabled people systems shaped by earlier decisions -- scarcity-based budgets, churn-driven staffing models, fragile funding structures, and policies that externalize risk. These unstable arrangements endure when organizations continue to build on them rather than dismantle them."}),"\n",(0,n.jsx)(t.p,{children:"Precarity does not happen on its own. It is the outcome of decisions, budgets, incentives, and policies -- or the refusal to build systems that allow disabled people to thrive. When stability is absent, the message is clear: disabled people must bear the risk others are protected from. Precarity becomes a form of structured disposability."}),"\n",(0,n.jsxs)(t.admonition,{title:"A biosocial perspective",type:"tip",children:[(0,n.jsx)(t.p,{children:"Precarity harms bodies, reshapes behavior, and emerges from institutional, economic, and cultural systems that normalize instability. This page uses a biosocial lens to show how scarcity-driven environments disable people -- not through singular events, but through chronic conditions."}),(0,n.jsx)(t.p,{children:"This page is a contribution to social medicine: mapping how precarity itself constitutes structural harm, and how its drivers and effects ripple across health, work, identity, and community."})]}),"\n",(0,n.jsx)(t.h2,{id:"why-it-happens",children:"Why It Happens"}),"\n",(0,n.jsx)(t.p,{children:"Precarity is created when institutions treat stability as optional rather than foundational.\nWhen leadership frames continuity as a luxury instead of a requirement, the systems disabled people depend on remain fragile, unpredictable, and unable to support sustained access."}),"\n",(0,n.jsx)(t.p,{children:"Precarity can gradually emerge as support systems thin out. Budgets contract, roles become temporary, workloads intensify, and once-reliable resources are spread across too few people. Over time, these material pressures accumulate into chronic instability."}),"\n",(0,n.jsx)(t.p,{children:"Precarity is propped up by austerity, gig economy logic, funding volatility, workforce churn, informal processes, systemic bias, and political indifference."}),"\n",(0,n.jsx)(t.p,{children:'Gig economy logic normalizes precarity. As work becomes outsourced, on-demand, and classification-resistant, institutions adopt the same \u201cflexible\u201d models -- temporary roles, contractor-heavy teams, "soft money" positions, churn-based staffing -- transferring instability to disabled people who depend on reliable structures for access.'}),"\n",(0,n.jsx)(t.p,{children:"Funding volatility intensifies precarity. Disability-centered work is often the least funded and the first to be cut when priorities shift. When funding cycles shorten, stability collapses. Sudden layoffs, funding shocks, leadership changes, or shifting priorities can amplify already unstable conditions, making fragile systems even less reliable."}),"\n",(0,n.jsx)(t.p,{children:"Workforce churn accelerates precarity. When teams rely on individual champions instead of institutional commitments, the departure of one person can destabilize entire accessibility pathways."}),"\n",(0,n.jsx)(t.p,{children:'Flexibility rhetoric justifies precarity. Organizations frame temporary staffing, unstable roles, and constant restructuring as "agile," "lean," or "responsive," even when this instability removes the dependable supports disabled people require. What is framed as agility is often a transfer of risk from institutions to individuals. What is sold as efficiency is often the erosion of safeguards that protect disabled people\u2019s capacity to participate.'}),"\n",(0,n.jsx)(t.p,{children:"Austerity drives precarity. When budgets shrink or are reallocated, the first roles cut are often the ones that safeguard access -- accessibility teams, disability services, support positions, and stabilizing infrastructure."}),"\n",(0,n.jsx)(t.p,{children:'Systemic bias sustains precarity. Disabled people are often assumed to be less productive, less essential, or less central to the "core mission." These assumptions rationalize underinvestment, unstable roles, and fragile supports.'}),"\n",(0,n.jsx)(t.p,{children:"Political indifference reinforces precarity. When rights, funding streams, or enforcement mechanisms are optional rather than guaranteed, disabled people must navigate environments where stability is never assured."}),"\n",(0,n.jsx)(t.p,{children:"Precarity persists when institutions expect individuals to absorb instability rather than designing environments that prevent it."}),"\n",(0,n.jsx)(t.h2,{id:"where-it-happens-enable-stages",children:"Where It Happens (ENABLE Stages)"}),"\n",(0,n.jsxs)(t.table,{children:[(0,n.jsx)(t.thead,{children:(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.th,{children:(0,n.jsx)(t.strong,{children:"ENABLE Stage"})}),(0,n.jsx)(t.th,{children:(0,n.jsx)(t.strong,{children:"How Precarity Shows Up"})})]})}),(0,n.jsxs)(t.tbody,{children:[(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.strong,{children:"Set Requirements that Include Accessibility"})}),(0,n.jsx)(t.td,{children:"Accessibility staffing, timelines, and budgets are unstable or unfunded, leaving requirements unsupported or unenforced."})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.strong,{children:"Create Accessible Content"})}),(0,n.jsx)(t.td,{children:"Content teams lack continuity; accessible formats are inconsistently maintained because staffing changes or contracted roles lapse."})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.strong,{children:"Design Accessible Experiences"})}),(0,n.jsx)(t.td,{children:"Inclusive design patterns disappear as teams churn, priorities shift, or contract designers rotate off projects."})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.strong,{children:"Develop Accessible Implementations"})}),(0,n.jsx)(t.td,{children:"Accessibility fixes are implemented on unstable foundations -- codebases, teams, or contracts likely to change before maintenance occurs."})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.strong,{children:"Test for Accessibility"})}),(0,n.jsx)(t.td,{children:"Testing is inconsistent because QA roles are temporary, underfunded, or eliminated during restructuring."})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.strong,{children:"Triage Accessibility Issues"})}),(0,n.jsx)(t.td,{children:"Issue triage fluctuates with staffing changes or shifting priorities; critical concerns are deprioritized when capacity drops."})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.strong,{children:"Iterate to Address Shortcomings"})}),(0,n.jsx)(t.td,{children:"Iterations stall because teams lack stable staffing or budgets to revisit accessibility work."})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.strong,{children:"Create Stopgaps"})}),(0,n.jsx)(t.td,{children:"Stopgaps become permanent because no stable resources exist to address underlying issues."})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.strong,{children:"Use Assistive Technologies"})}),(0,n.jsx)(t.td,{children:"AT support breaks when platforms change and there is no stable team to maintain compatibility."})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.strong,{children:"Augment with Third-Party Tools"})}),(0,n.jsx)(t.td,{children:"Third-party solutions disappear due to unsupported updates or abandoned maintenance, leaving users without fallback options."})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.strong,{children:"Change System Settings"})}),(0,n.jsx)(t.td,{children:"System-level accessibility settings are destabilized by updates with no commitment to restore or maintain compatibility."})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.strong,{children:"Create Workarounds"})}),(0,n.jsx)(t.td,{children:"Workarounds require ongoing upkeep when users cannot rely on stability in the systems they patch."})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.strong,{children:"Use Humans for Assistance"})}),(0,n.jsx)(t.td,{children:"Human assistance channels are understaffed, unstable, or dependent on volunteers, making support unpredictable."})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.strong,{children:"Submit Feedback to Creators"})}),(0,n.jsx)(t.td,{children:"Feedback goes unanswered or cycles through unstable support teams, leading to inconsistent responses."})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.strong,{children:"Assert One\u2019s Rights"})}),(0,n.jsx)(t.td,{children:"Legal protections become unstable due to shifting enforcement priorities, political pressure, or policy reversals."})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.strong,{children:"Stage a Protest"})}),(0,n.jsx)(t.td,{children:"Advocacy is weakened when disability organizations face their own precarity -- underfunding, staffing turnover, or burnout."})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.strong,{children:"Switch to an Alternative"})}),(0,n.jsx)(t.td,{children:"When alternatives may not exist or may be equally unstable, switching only trades one form of precarity for another."})]})]})]}),"\n",(0,n.jsx)(t.h2,{id:"how-it-disables",children:"How It Disables"}),"\n",(0,n.jsx)(t.p,{children:"Precarity disables by destabilizing the conditions needed to maintain ability. It removes continuity, predictability, and reliability -- replacing them with uncertainty and risk."}),"\n",(0,n.jsx)(t.p,{children:"Precarity disables by:"}),"\n",(0,n.jsxs)(t.ul,{children:["\n",(0,n.jsx)(t.li,{children:"Undermining continuity: people cannot rely on the same tools, supports, or policies from one month to the next."}),"\n",(0,n.jsx)(t.li,{children:"Forcing compensations: individuals must repeatedly rebuild stability that institutions failed to provide."}),"\n",(0,n.jsxs)(t.li,{children:["Collapsing pathways: precarity narrows the range of viable educational, professional, relational, and health-related trajectories, reducing the ",(0,n.jsx)(t.em,{children:"futures a person can imagine"}),(0,n.jsx)(t.sup,{children:(0,n.jsx)(t.a,{href:"#user-content-fn-1",id:"user-content-fnref-1","data-footnote-ref":!0,"aria-describedby":"footnote-label",children:"1"})})," or realistically reach."]}),"\n",(0,n.jsx)(t.li,{children:"Interrupting autonomy: planning becomes impossible when everything is contingent."}),"\n",(0,n.jsx)(t.li,{children:"Increasing cognitive load: constant vigilance is required to anticipate collapse."}),"\n",(0,n.jsx)(t.li,{children:"Draining capacity: survival labor replaces participation, creation, or progression."}),"\n",(0,n.jsx)(t.li,{children:"Increasing risk: instability leads to lapses in care, coverage, access, and safety."}),"\n",(0,n.jsx)(t.li,{children:"Eroding trust: people learn that nothing is dependable and reduce engagement as self-protection."}),"\n",(0,n.jsx)(t.li,{children:"Displacing labor: individuals must construct the stability the institution never provided -- tracking updates, inventing routines, and building personal safety nets because no reliable system exists upstream."}),"\n"]}),"\n",(0,n.jsxs)(t.p,{children:["Precarity disables by removing ",(0,n.jsx)(t.em,{children:"stability"})," -- the foundation of ability itself."]}),"\n",(0,n.jsx)(t.h2,{id:"why-it-matters",children:"Why It Matters"}),"\n",(0,n.jsx)(t.p,{children:"Precarity gets into the body, reshapes behavior, and destabilizes systems meant to provide care and continuity."}),"\n",(0,n.jsx)(t.p,{children:"Precarity is not just instability -- it is a social and biosocial harm. It induces stress, burnout, hypervigilance, and fear of collapse; increases hospitalization risk; disrupts care routines; destabilizes health management; forces compensation; forecloses futures; marginalizes care; erodes trust; stunts progress; reinforces social devaluation; inflicts harm; and rewires behavior."}),"\n",(0,n.jsx)(t.p,{children:"Precarity forces people with disabilities to compensate. They must fill gaps, anticipate failures, and rebuild stability themselves. These compensations are not optional -- they are survival strategies -- but they come at physical and emotional cost."}),"\n",(0,n.jsx)(t.p,{children:"Precarity induces stress. Chronic instability forces people to monitor threats, juggle unmet needs, and brace for disruption -- taxing cognitive, emotional, and physiological systems."}),"\n",(0,n.jsx)(t.p,{children:"Precarity produces burnout. Constant vigilance and endless compensations drain energy faster than it can be replenished. What should be sustainable becomes exhausting; what should be manageable becomes overwhelming."}),"\n",(0,n.jsx)(t.p,{children:"Precarity breeds hypervigilance. When support structures are unreliable, people learn to anticipate breakdowns before they occur. This sustained state of alertness is harmful on its own -- disrupting sleep, impairing concentration, and reducing capacity for daily living."}),"\n",(0,n.jsx)(t.p,{children:"Precarity creates a fear of collapse. When the environment is fragile, any setback -- an update, a policy shift, a staffing change -- threatens to upend essential routines. This fear shapes decisions, limits participation, and restricts autonomy."}),"\n",(0,n.jsx)(t.p,{children:"Precarity increases hospitalization risk. Instability disrupts medication schedules, care coordination, accessible transit, appointment systems, and follow-up routines. When care is interrupted, health declines -- sometimes rapidly."}),"\n",(0,n.jsx)(t.p,{children:"Precarity disrupts care routines. Even well-designed systems fail when maintenance is unstable. Missed updates, lost documentation, shifting providers, and inconsistent communication leave care pathways fractured and unreliable."}),"\n",(0,n.jsx)(t.p,{children:"Precarity destabilizes health management. Without predictable support -- for scheduling, transportation, digital access, or continuity of tools -- self-management becomes more difficult. Small lapses compound into health crises."}),"\n",(0,n.jsx)(t.p,{children:"Precarity forecloses futures. It diminishes access to education, careers, relationships, stable housing, and long-term health -- not because of individual capacity, but because pathways are structurally removed. Over time, this alters life trajectories, limits social mobility, and contributes directly to reduced life expectancy for disabled people navigating precarious systems."}),"\n",(0,n.jsx)(t.p,{children:"Precarity marginalizes care. When care depends on unstable funding or personnel, it becomes fragile -- easily deprioritized, dismissed, or delayed. Access that requires stability collapses without it."}),"\n",(0,n.jsx)(t.p,{children:"Precarity erodes trust. When people experience instability, they stop expecting support, stop reporting issues, and disengage from systems that repeatedly fail them."}),"\n",(0,n.jsx)(t.p,{children:"Precarity stunts progress. Accessibility requires stable teams, resources, and commitments. Precarity prevents these foundation layers from forming -- leaving inclusion undeveloped rather than merely temporary."}),"\n",(0,n.jsx)(t.p,{children:"Precarity reinforces social devaluation. When disabled people are placed in unstable environments while others receive guaranteed support, the system communicates that their stability is optional and their participation expendable."}),"\n",(0,n.jsx)(t.p,{children:"Precarity inflicts harm. It creates conditions where lives, jobs, and care routines can collapse without warning. It turns every decision into a gamble and every day into a negotiation with risk."}),"\n",(0,n.jsx)(t.p,{children:"Precarity rewires behavior. People adapt by minimizing exposure: avoiding updates, lowering expectations, withdrawing from opportunities, and treating instability as inevitable. What looks like disengagement is often self-preservation."}),"\n",(0,n.jsx)(t.h2,{id:"real-world-examples",children:"Real-World Examples"}),"\n",(0,n.jsxs)(t.ul,{children:["\n",(0,n.jsx)(t.li,{children:"A disability services office loses two staff members during budget cuts; accommodations slow to a crawl."}),"\n",(0,n.jsx)(t.li,{children:"A research lab dependent on soft-money positions dissolves after a funding gap, leaving disabled researchers without continuity or support."}),"\n",(0,n.jsx)(t.li,{children:"A contracted accessibility team is terminated during reorganization, breaking the maintenance cycle that ensured ongoing compatibility."}),"\n",(0,n.jsx)(t.li,{children:"AT support is inconsistent because the vendor rotates through temporary development teams every quarter, leaving no sustained expertise to maintain compatibility."}),"\n",(0,n.jsx)(t.li,{children:'A disabled employee loses their job during layoffs that target "nonessential" roles.'}),"\n",(0,n.jsx)(t.li,{children:"A health portal\u2019s accessibility regressions accumulate because the vendor rotates teams every quarter."}),"\n",(0,n.jsx)(t.li,{children:"A grant-funded accessibility project ends abruptly, eliminating the only reliable support channel."}),"\n"]}),"\n",(0,n.jsx)(t.h2,{id:"what-care-sounds-like",children:"What Care Sounds Like"}),"\n",(0,n.jsxs)(t.blockquote,{children:["\n",(0,n.jsx)(t.p,{children:'"We\u2019re building accessibility work on stable, long-term foundations -- not temporary roles."'}),"\n",(0,n.jsx)(t.p,{children:'"Continuity matters. We\u2019ve budgeted for it."'}),"\n",(0,n.jsx)(t.p,{children:'"We\u2019re designing processes that don\u2019t collapse when people leave."'}),"\n",(0,n.jsx)(t.p,{children:'"This accessibility work will not be cut or deprioritized during restructuring."'}),"\n",(0,n.jsx)(t.p,{children:'"We\u2019re ensuring stable funding so users aren\u2019t left without support."'}),"\n",(0,n.jsx)(t.p,{children:'"We treat stability as required, not optional."'}),"\n",(0,n.jsx)(t.p,{children:'"Access is not dependent on individual champions -- it\u2019s embedded in the institution."'}),"\n"]}),"\n",(0,n.jsx)(t.h2,{id:"what-neglect-sounds-like",children:"What Neglect Sounds Like"}),"\n",(0,n.jsxs)(t.blockquote,{children:["\n",(0,n.jsx)(t.p,{children:'"We\u2019ll get to accessibility if we have the capacity."'}),"\n",(0,n.jsx)(t.p,{children:'"We\u2019re phasing out this role -- someone else can pick it up."'}),"\n",(0,n.jsx)(t.p,{children:'"We lost funding, so accessibility will have to wait."'}),"\n",(0,n.jsx)(t.p,{children:'"That feature isn\u2019t stable, but it\u2019s not a priority."'}),"\n",(0,n.jsx)(t.p,{children:'"We can\u2019t guarantee ongoing support for that."'}),"\n",(0,n.jsx)(t.p,{children:'"We\u2019re reorganizing -- things might change."'}),"\n",(0,n.jsx)(t.p,{children:'"We don\u2019t have the resources right now."'}),"\n",(0,n.jsx)(t.p,{children:'"That depends on next year\u2019s budget."'}),"\n",(0,n.jsx)(t.p,{children:'"Our capacity changes month to month."'}),"\n"]}),"\n",(0,n.jsx)(t.hr,{}),"\n",(0,n.jsxs)(t.blockquote,{children:["\n",(0,n.jsx)(t.p,{children:"We got somethin', we both know it, we don't talk too much about it. Ain't no real big secret all the same. Somehow we get around it."}),"\n",(0,n.jsx)(t.p,{children:"-- Tom Petty"}),"\n"]}),"\n",(0,n.jsx)(t.hr,{}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.em,{children:"Edited by Lawrence Weru, S.M., Harvard Medical School (Department of Global Health and Social Medicine), B.A.-B.S., Florida State"})}),"\n",(0,n.jsx)(t.hr,{}),"\n","\n",(0,n.jsxs)(t.section,{"data-footnotes":!0,className:"footnotes",children:[(0,n.jsx)(t.h2,{className:"sr-only",id:"footnote-label",children:"Footnotes"}),"\n",(0,n.jsxs)(t.ol,{children:["\n",(0,n.jsxs)(t.li,{id:"user-content-fn-1",children:["\n",(0,n.jsxs)(t.p,{children:["Kafer, Alison. 2013. \u201cIntroduction.\u201d In Feminist, Queer, Crip. Bloomington, IN: Indiana\xa0University Press, 1\u201324. ",(0,n.jsx)(t.a,{href:"#user-content-fnref-1","data-footnote-backref":"","aria-label":"Back to reference 1",className:"data-footnote-backref",children:"\u21a9"})]}),"\n"]}),"\n"]}),"\n"]})]})}function h(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}},8453:(e,t,i)=>{i.d(t,{R:()=>a,x:()=>o});var s=i(6540);const n={},r=s.createContext(n);function a(e){const t=s.useContext(r);return s.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:a(e.components),s.createElement(r.Provider,{value:t},e.children)}}}]);